def transform(grid):
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 1]
    if len(points) < 2:
        return out
    points.sort()
    # The given markers lie on a diagonal arithmetic progression.
    dr = points[1][0] - points[0][0]
    dc = points[1][1] - points[0][1]
    if dr <= 0 or dc <= 0:
        return out
    if any((r - points[0][0]) * dc != (c - points[0][1]) * dr for r, c in points):
        return out
    steps = [points[i + 1][0] - points[i][0] for i in range(len(points) - 1)]
    step = steps[0]
    for d in steps[1:]:
        step = gcd(step, d)
    if step <= 0 or any((r - points[0][0]) % step for r, _ in points):
        return out
    r, c = points[-1]
    while r + step < len(out) and c + step < len(out[0]):
        r += step
        c += step
        if out[r][c] == 0:
            out[r][c] = 2
    return out
